args.command:
cd /office; python3 - <<'PYEOF'
import re, glob
# 册名映射：所有现存纪要为6/2~6/7签发，均早于6/9换册 → 用原册
onsite={"东港":"潮册","西湾":"栈册","南站":"桐册","北仓":"丁册"}
station_of={"J01":"东港","J02":"东港","J03":"东港","J04":"西湾","J05":"西湾","J06":"西湾",
"J07":"南站","J08":"南站","J09":"南站","J10":"北仓","J11":"北仓","J12":"北仓"}
obj={"J01":"HZ-A","J02":"JL-B","J03":"NP-B","J04":"HZ-B","J05":"YC-A","J06":"QH-B",
"J07":"JL-A","J08":"BA-B","J09":"QH-A","J10":"NP-A","J11":"YC-B","J12":"BA-A"}
weituo={"东港":("A",9),"西湾":("B",11),"南站":("B",11),"北仓":("A",9)}
# day -> sender date (for record)
daymap={"06-02":2,"06-04":4,"06-05":5,"06-06":6,"06-07":7}
clauses=[]  # dict per 议案-现场
for folder,d in daymap.items():
    for path in sorted(glob.glob(f"inbox/{folder}/*联席纪要.txt")):
        txt=open(path,encoding="utf-8").read()
        station=re.search(r"(\S+?)联席纪要",txt).group(1)
        for b in re.split(r"\n(?=议案 )",txt):
            m=re.match(r"议案\s+(\d+)\s+客户\s+(J\d+)",b)
            if not m: continue
            yian,case=m.group(1),m.group(2)
            for line in b.splitlines():
                cm=re.match(r"(\S+册)｜(.*)",line.strip())
                if not cm: continue
                book,body=cm.group(1),cm.group(2)
                if book!=onsite[station]: continue
                signer="代办" if "代办" in body else "本部"
                stt="待批" if "待批" in body else ("草案" if "草案" in body else "正本")
                per=re.search(r"六月(\d+)日至(\d+)日",body)
                q=p=None
                m1=re.search(r"核给(\d+)席.*?优先号(\d+)",body); m2=re.search(r"办理顺位(\d+).*?额度(\d+)席",body); m3=re.search(r"留位为(\d+)席.*?优先号(\d+)",body)
                if m1:q,p=int(m1.group(1)),int(m1.group(2))
                elif m2:p,q=int(m2.group(1)),int(m2.group(2))
                elif m3:q,p=int(m3.group(1)),int(m3.group(2))
                clauses.append(dict(day=d,station=station,case=case,yian=int(yian),signer=signer,stt=stt,
                    q=q,p=p,start=int(per.group(1)),end=int(per.group(2)),form=("核给" if m1 else "顺位" if m2 else "留位")))

def valid_on(c, d):
    if c["stt"]!="正本": return False
    if not (c["start"]<=d<=c["end"]): return False
    if c["signer"]=="代办":
        xs,mo=weituo[c["station"]]; caseser=obj[c["case"]].split("-")[1]
        if not (xs==caseser and 9<=d<=mo): return False
    return True

cases=[f"J{i:02d}" for i in range(1,13)]
print("=== 各案 现场册条款（全部）===")
for cs in cases:
    print("--",cs, station_of[cs], obj[cs], "站委", weituo[station_of[cs]])
    for c in sorted([x for x in clauses if x["case"]==cs], key=lambda x:(x["day"],x["yian"])):
        v9=valid_on(c,9); v10=valid_on(c,10)
        print(f"   D{c['day']} 议案{c['yian']} {c['form']} 额{c['q']} 优{c['p']} {c['start']}-{c['end']} {c['signer']}/{c['stt']}  d9合法={v9} d10合法={v10}")

print("\n=== 9日批文 / 10日候选批文（max(生效日,流水)，仅今日已知）===")
for cs in cases:
    def pick(d):
        cand=[c for c in clauses if c["case"]==cs and valid_on(c,d)]
        if not cand: return ("章程",None)
        best=max(cand,key=lambda c:(c["start"],c["yian"]))
        return (str(best["yian"]),best)
    p9,b9=pick(9); p10,b10=pick(10)
    print(cs,"九日:",p9, (b9["q"],b9["p"],b9["start"],b9["end"]) if b9 else "","| 十日候选:",p10,(b10["q"],b10["p"],b10["start"],b10["end"]) if b10 else "")
PYEOF
